   147  /* crc24q_hash() - compute the CRC24Q for "len" bytes of data in "data"
   148   *
   149   * Return: the 24 bit hash
   150   */
   151  unsigned crc24q_hash(unsigned char *data, int len)
   152  {
   153      int i;
   154      unsigned crc = 0;
   155
   156      for (i = 0; i < len; i++) {
   157          crc = (crc << 8) ^ crc24q[data[i] ^ (unsigned char)(crc >> 16)];
   158      }
   159
   160      crc &= 0x00ffffff;
   161
   162      return crc;
   163  }
   164
   165  #define LO(x)   (unsigned char)((x) & 0xff)
   166  #define MID(x)  (unsigned char)(((x) >> 8) & 0xff)
   167  #define HI(x)   (unsigned char)(((x) >> 16) & 0xff)
   168
   169  #ifdef __UNUSED__
   170  void crc24q_sign(unsigned char *data, int len)
   171  {
   172      unsigned crc = crc24q_hash(data, len);
   173
   174      data[len] = HI(crc);
   175      data[len + 1] = MID(crc);
   176      data[len + 2] = LO(crc);
   177  }
   178  #endif  // __UNUSED__
   179
   180  // len includes the data to CRC, and the 3 CRC bytes to check with.
   181  bool crc24q_check(unsigned char *data, int len)
   182  {
   183      unsigned crc = crc24q_hash(data, len - 3);
   184
   185      return (((data[len - 3] == HI(crc)) &&
   186               (data[len - 2] == MID(crc)) &&
   187               (data[len - 1] == LO(crc))));
   188  }
